sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    if (isLoading) {
        return;
    }
    if (newValue == "investment") {
		g_form.clearValue("u_project_type");
		g_form.setDisplay("u_project_type", true);
        g_form.setDisplay("u_number_range", true);
        g_form.setDisplay("main_expense", true);
        g_form.setDisplay("sub_expense", true);
		g_form.clearValue("product_category");
		g_form.clearValue("activity");
		g_form.clearValue("campaign");
		g_form.clearValue("advertising_type");
		g_form.clearValue('channel');
		g_form.setDisplay('channel',false);
		g_form.clearValue('department');
		g_form.clearValue('activity_type');
		g_form.setDisplay("activity_type", false);
		g_form.setDisplay('department',false);
		g_form.setDisplay("product_category", false);
        g_form.setDisplay("activity", false);
        g_form.setDisplay("campaign", false);
		g_form.setDisplay("advertising_type",false);

    } else if (newValue == "marketing expenses") {
		g_form.clearValue("u_project_type");
		g_form.setDisplay("u_project_type", true);
        g_form.setDisplay("u_number_range", true);
        g_form.setDisplay("product_category", true);
        g_form.setDisplay("activity", true);
        g_form.setDisplay("campaign", true);
		g_form.clearValue("advertising_type");
		g_form.clearValue("main_expense");
		g_form.clearValue("sub_expense");
		g_form.clearValue('channel');
		g_form.setDisplay('channel',false);
		g_form.clearValue('department');
		g_form.clearValue('activity_type');
		g_form.setDisplay("activity_type", false);
		g_form.setDisplay('department',false);
		g_form.setDisplay("advertising_type",false);
        g_form.setDisplay("main_expense", false);
        g_form.setDisplay("sub_expense", false);

    }
	else if(newValue == "advertising expenses"){
		g_form.clearValue("u_project_type");
		g_form.setDisplay("u_project_type", true);
		g_form.setDisplay("u_number_range", true);
        g_form.setDisplay("product_category", true);
		g_form.setDisplay("advertising_type",true);
		g_form.setDisplay("sub_expense", true);
		g_form.clearValue("main_expense");
		g_form.clearValue("activity");
		g_form.clearValue("campaign");
		g_form.clearValue('channel');
		g_form.clearValue('activity_type');
		g_form.setDisplay("activity_type", false);
		g_form.setDisplay('channel',false);
		g_form.clearValue('department');
		g_form.setDisplay('department',false);
        g_form.setDisplay("main_expense", false);
		g_form.setDisplay("activity", false);
        g_form.setDisplay("campaign", false);

	}
	else if(newValue == "general and admin expenses"){
		g_form.clearValue("u_project_type");
		g_form.setDisplay("u_project_type", true);
		g_form.setDisplay("u_number_range", true);
        g_form.setDisplay("department", true);
		g_form.setDisplay("main_expense", true);
		g_form.setDisplay("sub_expense", true);
		g_form.clearValue("advertising_type");
		g_form.clearValue("activity");
		g_form.clearValue("campaign");
		g_form.clearValue('channel');
		g_form.clearValue("product_category");
		g_form.clearValue('activity_type');
		g_form.setDisplay("activity_type", false);
		g_form.setDisplay("product_category", false);
		g_form.setDisplay('channel',false);
        g_form.setDisplay("advertising_type",false);
		g_form.setDisplay("activity", false);
        g_form.setDisplay("campaign", false);

	}
	else if(newValue == "project sales"){
		g_form.clearValue("u_project_type");
		g_form.setDisplay("u_project_type", true);
		g_form.setDisplay("u_number_range", true);
        g_form.setDisplay("main_expense", true);
		g_form.setDisplay("sub_expense", true);
		g_form.clearValue("channel");
		g_form.clearValue("activity");
		g_form.clearValue("campaign");
		g_form.clearValue("advertising_type");
		g_form.clearValue("department");
		g_form.clearValue("product_category");
		g_form.clearValue('activity_type');
		g_form.setDisplay("activity_type", false);
		g_form.setDisplay("product_category",false);
		g_form.setDisplay("channel", false);
		g_form.setDisplay("department", false);
		g_form.setDisplay("advertising_type",false);
		g_form.setDisplay("activity", false);
        g_form.setDisplay("campaign", false);

	}
	else if(newValue == "regional expense"){
		g_form.clearValue("u_project_type");
		g_form.setDisplay("u_project_type", true);
		g_form.setDisplay("u_number_range", true);
        g_form.setDisplay("activity_type", true);
		g_form.setDisplay("channel",true);
		g_form.setDisplay("sub_expense", true);
		g_form.clearValue("main_expense");
		g_form.clearValue("activity");
		g_form.clearValue("campaign");
		g_form.clearValue('advertising_type');
		g_form.clearValue("department");
		g_form.clearValue("product_category");
		g_form.setDisplay("department", false);
		g_form.setDisplay("advertising_type",false);
        g_form.setDisplay("main_expense", false);
		g_form.setDisplay("activity", false);
        g_form.setDisplay("campaign", false);
		g_form.setDisplay("product_category",false);

	}

	else{
		g_form.setDisplay("u_project_type", false);
	    g_form.setDisplay("u_number_range", false);
        g_form.setDisplay("main_expense", false);
        g_form.setDisplay("sub_expense", false);	
		g_form.setDisplay("product_category", false);
        g_form.setDisplay("activity", false);
        g_form.setDisplay("campaign", false);
		g_form.setDisplay("advertising_type",false);
		g_form.setDisplay("activity_type", false);
		g_form.setDisplay('channel',false);
		g_form.setDisplay('department',false);
	}

}
